<body>
  <header class="topbar">
    <div>
      <p class="eyebrow">Shipyard</p>
      <h1>Release <span id="release-name">v1.4</span> readiness</h1>
    </div>
    <span class="badge" id="release-date">Target: 2026-11-10</span>
  </header>

  <main>
    <section class="kpis" aria-label="Release metrics">
      <article class="kpi"><h2>Open tasks</h2><p id="kpi-open">–</p></article>
      <article class="kpi"><h2>Completed</h2><p id="kpi-done">–</p></article>
      <article class="kpi kpi-alert"><h2>Overdue</h2><p id="kpi-overdue">–</p></article>
      <article class="kpi"><h2>Notes</h2><p id="kpi-notes">–</p></article>
    </section>

    <section class="panel" aria-labelledby="tasks-title">
      <div class="panel-head">
        <h2 id="tasks-title">Release tasks</h2>
        <div class="filters">
          <label>Owner <select id="owner-filter"><option value="">All owners</option></select></label>
          <label>Status
            <select id="status-filter">
              <option value="pending">Pending</option>
              <option value="done">Done</option>
              <option value="all">All</option>
            </select>
          </label>
        </div>
      </div>
      <table class="tasks">
        <thead><tr><th>Task</th><th>Owner</th><th>Due</th><th>Status</th></tr></thead>
        <tbody id="tasks-body"></tbody>
      </table>
      <p class="empty" id="tasks-empty" hidden>No tasks match these filters.</p>
    </section>

    <section class="panel" aria-labelledby="notes-title">
      <div class="panel-head">
        <h2 id="notes-title">Engineering notes</h2>
        <input id="notes-search" type="search" placeholder="Search notes" aria-label="Search notes">
      </div>
      <div class="tags" id="tag-chips" aria-label="Filter by tag"></div>
      <ul class="notes" id="notes-list"></ul>
      <p class="empty" id="notes-empty" hidden>No notes found.</p>
    </section>
  </main>

  <footer>Data from <code>/api/tasks</code> and <code>/api/notes</code> · <span id="last-updated">loading…</span></footer>
  <script type="module" src="js/main.js"></script>
</body>
</html>
// Entry point: owns the state object and wires events to data loading and rendering.

import { fetchNotes, fetchTasks } from "./api.js";
import { renderKpis, renderNotes, renderOwnerFilter, renderTags, renderTasks, renderUpdated } from "./render.js";

const state = { tasks: [], notes: [], owner: "", status: "pending", q: "", tag: "" };

async function refreshNotes() {
  state.notes = await fetchNotes(state);
  renderNotes(state);
  renderTags(state, toggleTag);
  renderKpis(state);
}

function toggleTag(tag) {
  state.tag = state.tag === tag ? "" : tag;
  return refreshNotes();
}

async function init() {
  document.getElementById("owner-filter").addEventListener("change", (e) => {
    state.owner = e.target.value;
    renderTasks(state);
  });
  document.getElementById("status-filter").addEventListener("change", (e) => {
    state.status = e.target.value;
    renderTasks(state);
  });
  let timer;
  document.getElementById("notes-search").addEventListener("input", (e) => {
    clearTimeout(timer);
    timer = setTimeout(() => {
      state.q = e.target.value.trim();
      refreshNotes();
    }, 200);
  });
  [state.tasks, state.notes] = await Promise.all([fetchTasks(), fetchNotes(state)]);
  renderKpis(state);
  renderOwnerFilter(state);
  renderTasks(state);
  renderTags(state, toggleTag);
  renderNotes(state);
  renderUpdated();
}

init();
// The only module that talks to the Shipyard HTTP API.

async function getJson(url, label) {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error(`Could not load ${label}`, err);
    return [];
  }
}

export function fetchTasks() {
  return getJson("/api/tasks", "tasks");
}

export function fetchNotes({ q = "", tag = "" } = {}) {
  const params = new URLSearchParams();
  if (q) params.set("q", q);
  if (tag) params.set("tag", tag);
  return getJson(`/api/notes?${params}`, "notes");
}
