import { fetchNotes, fetchTasks } from "./api.js";
import { renderKpis, renderNotes, renderOwnerFilter, renderTags, renderTasks, renderUpdated } from "./render.js";

const state = { tasks: [], notes: [], owner: "", status: "pending", q: "", tag: "" };

async function refreshNotes() {
  state.notes = await fetchNotes(state);
  renderNotes(state);
  renderTags(state, toggleTag);
  renderKpis(state);
}

function toggleTag(tag) {
  state.tag = state.tag === tag ? "" : tag;
  return refreshNotes();
}

async function init() {
  document.getElementById("owner-filter").addEventListener("change", (e) => {
    state.owner = e.target.value;
    renderTasks(state);
  });
  document.getElementById("status-filter").addEventListener("change", (e) => {
    state.status = e.target.value;
    renderTasks(state);
  });
  let timer;
  document.getElementById("notes-search").addEventListener("input", (e) => {
    clearTimeout(timer);
    timer = setTimeout(() => {
      state.q = e.target.value.trim();
      refreshNotes();
    }, 200);
  });
  [state.tasks, state.notes] = await Promise.all([fetchTasks(), fetchNotes(state)]);
  renderKpis(state);
  renderOwnerFilter(state);
  renderTasks(state);
  renderTags(state, toggleTag);
  renderNotes(state);
  renderUpdated();
}

init();
// The only module that talks to the Shipyard HTTP API.

async function getJson(url, label) {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error(`Could not load ${label}`, err);
    return [];
  }
}

export function fetchTasks() {
  return getJson("/api/tasks", "tasks");
}

export function fetchNotes({ q = "", tag = "" } = {}) {
  const params = new URLSearchParams();
  if (q) params.set("q", q);
  if (tag) params.set("tag", tag);
  return getJson(`/api/notes?${params}`, "notes");
}
// DOM rendering. Each function owns one region of index.html and reads only the state it is given.

import { allTags, computeKpis, escapeHtml, filterTasks, formatBody, isOverdue, uniqueOwners } from "./logic.js";

const $ = (id) => document.getElementById(id);

export function renderKpis(state) {
  const k = computeKpis(state.tasks, state.notes);
  $("kpi-open").textContent = k.open;
  $("kpi-done").textContent = k.done;
  $("kpi-overdue").textContent = k.overdue;
  $("kpi-notes").textContent = k.notes;
}

export function renderOwnerFilter(state) {
  const select = $("owner-filter");
  const current = select.value;
  select.innerHTML = '<option value="">All owners</option>' +
    uniqueOwners(state.tasks).map((o) => `<option value="${escapeHtml(o)}">${escapeHtml(o)}</option>`).join("");
  select.value = current;
}

export function renderTasks(state) {
  const rows = filterTasks(state.tasks, state);
  $("tasks-body").innerHTML = rows.map((t) => `
    <tr class="${isOverdue(t) ? "overdue" : ""}">
      <td>${escapeHtml(t.title)}</td>
      <td>${escapeHtml(t.owner || "–")}</td>
      <td>${escapeHtml(t.due || "–")}</td>
      <td><span class="status status-${t.status}">${t.status}</span></td>
    </tr>`).join("");
  $("tasks-empty").hidden = rows.length > 0;
}

export function renderTags(state, onToggle) {
  const box = $("tag-chips");
  box.innerHTML = allTags(state.notes).map((tag) =>
    `<button class="chip ${tag === state.tag ? "active" : ""}" data-tag="${escapeHtml(tag)}">#${escapeHtml(tag)}</button>`).join("");
  box.querySelectorAll(".chip").forEach((chip) => chip.addEventListener("click", () => onToggle(chip.dataset.tag)));
}

export function renderNotes(state) {
  $("notes-list").innerHTML = state.notes.map((n) => `
    <li>
      <h3>${escapeHtml(n.title)}</h3>
      <p>${formatBody(n.body)}</p>
      <div class="note-tags">${(n.tags || []).map((t) => `<span>#${escapeHtml(t)}</span>`).join("")}</div>
    </li>`).join("");
  $("notes-empty").hidden = state.notes.length > 0;
}

export function renderUpdated() {
  $("last-updated").textContent = `updated ${new Date().toLocaleTimeString()}`;
}
// Pure, DOM-free rules for the release dashboard. Covered by dashboard/tests/logic.test.mjs.

export function todayIso(now = new Date()) {
  return now.toISOString().slice(0, 10);
}

export function isOverdue(task, today = todayIso()) {
  return task.status !== "done" && Boolean(task.due) && task.due < today;
}

export function filterTasks(tasks, { owner = "", status = "pending" } = {}) {
  return tasks
    .filter((t) => (status === "all" ? true : t.status === status))
    .filter((t) => (owner ? t.owner === owner : true))
    .sort((a, b) => (a.due || "9999-12-31").localeCompare(b.due || "9999-12-31") || a.id - b.id);
}

export function computeKpis(tasks, notes, today = todayIso()) {
  return {
    open: tasks.filter((t) => t.status !== "done").length,
    done: tasks.filter((t) => t.status === "done").length,
    overdue: tasks.filter((t) => isOverdue(t, today)).length,
    notes: notes.length,
  };
}

export function uniqueOwners(tasks) {
  return [...new Set(tasks.map((t) => t.owner).filter(Boolean))].sort();
}

export function allTags(notes) {
  return [...new Set(notes.flatMap((n) => n.tags || []))].sort();
}

export function escapeHtml(text) {
  return String(text ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

export function formatBody(body) {
  return String(body ?? "").replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
}

