// Release notes panel: pure render/markdown helpers (node-importable) plus browser wiring.
// Every API value is passed through escapeHtml before it reaches innerHTML.

export const RELEASE_VERSION_RE = /^v\d+\.\d+(\.\d+)?$/;

export function isValidVersion(version) {
  return typeof version === "string" && RELEASE_VERSION_RE.test(version);
}

export function releaseNotesUrl(version, format = "") {
  if (!isValidVersion(version)) throw new Error(`invalid release version: ${version}`);
  const base = `/api/releases/${encodeURIComponent(version)}/notes`;
  return format === "markdown" ? `${base}?format=markdown` : base;
}

export function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export function firstBodyLine(body) {
  for (const line of String(body ?? "").split(/\r?\n/)) {
    const t = line.trim();
    if (t) return t;
  }
  return "";
}

export function renderNoteItem(note) {
  const n = note || {};
  const line = firstBodyLine(n.body);
  const tags = (Array.isArray(n.tags) ? n.tags : [])
    .map((t) => `<span>#${escapeHtml(t)}</span>`)
    .join("");
  return `<li><h4>${escapeHtml(n.title)}</h4>`
    + (line ? `<p>${escapeHtml(line)}</p>` : "")
    + (tags ? `<div class="note-tags">${tags}</div>` : "")
    + `</li>`;
}

export function renderSection(section) {
  const s = section || {};
  const notes = Array.isArray(s.notes) ? s.notes : [];
  return `<section class="release-section" data-section="${escapeHtml(s.key)}">`
    + `<h3>${escapeHtml(s.title)} <span class="release-count">${notes.length}</span></h3>`
    + `<ul class="notes">${notes.map(renderNoteItem).join("")}</ul></section>`;
}

function sectionsOf(data) {
  return data && Array.isArray(data.sections) ? data.sections : [];
}

export function renderReleaseNotesHtml(data) {
  const sections = sectionsOf(data);
  if (!sections.length) {
    return `<p class="empty">No notes tagged <code>release:${escapeHtml(data && data.version)}</code> yet.</p>`;
  }
  return sections.map(renderSection).join("");
}

export function summaryText(data) {
  const sections = sectionsOf(data);
  const count = data && Number.isInteger(data.count)
    ? data.count
    : sections.reduce((n, s) => n + ((s.notes || []).length), 0);
  if (!count) return "No notes yet";
  const sec = sections.length;
  return `${count} ${count === 1 ? "note" : "notes"} in ${sec} ${sec === 1 ? "section" : "sections"}`;
}

export function buildMarkdown(data) {
  const lines = [`# Release ${(data && data.version) || ""}`.trimEnd()];
  for (const s of sectionsOf(data)) {
    lines.push("", `## ${s.title}`);
    for (const note of s.notes || []) {
      const line = firstBodyLine(note.body);
      lines.push(line ? `- ${note.title}: ${line}` : `- ${note.title}`);
    }
  }
  return lines.join("\n") + "\n";
}

// ---- Browser-only helpers (touch fetch/document/navigator only when called) ----

export async function fetchReleaseNotes(version) {
  try {
    const res = await fetch(releaseNotesUrl(version));
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.json();
  } catch (err) {
    console.error("Could not load release notes", err);
    return null;
  }
}

export async function fetchReleaseMarkdown(version) {
  try {
    const res = await fetch(releaseNotesUrl(version, "markdown"));
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return await res.text();
  } catch (err) {
    console.error("Could not load release markdown", err);
    return null;
  }
}

export async function copyText(text) {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly", "");
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand("copy");
    ta.remove();
    return ok;
  } catch (err) {
    console.error("Could not copy", err);
    return false;
  }
}

export async function initReleaseNotes() {
  const body = document.getElementById("release-notes-body");
  const summary = document.getElementById("release-notes-summary");
  const button = document.getElementById("release-notes-copy");
  const status = document.getElementById("release-notes-status");
  if (!body || !button) return;
  const nameEl = document.getElementById("release-name");
  const version = nameEl ? nameEl.textContent.trim() : "v1.4";

  let flash;
  const say = (msg) => {
    status.textContent = msg;
    clearTimeout(flash);
    flash = setTimeout(() => { status.textContent = ""; }, 3000);
  };

  button.addEventListener("click", async () => {
    const md = await fetchReleaseMarkdown(version);
    if (md === null) return say("Could not load notes");
    say((await copyText(md)) ? "Copied!" : "Copy failed");
  });

  const data = await fetchReleaseNotes(version);
  if (!data) {
    body.innerHTML = `<p class="empty">Release notes unavailable.</p>`;
    summary.textContent = "";
    return;
  }
  summary.textContent = summaryText(data);
  body.innerHTML = renderReleaseNotesHtml(data);
}
