"""Release notes: group notes tagged `release:<version>` into ordered sections. No HTTP, no SQL."""

from __future__ import annotations

import re
from typing import Any

from .service import NoteService, ValidationError

VERSION_RE = re.compile(r"v\d+\.\d+(\.\d+)?", re.ASCII)
MAX_TAG = 30

# (key, title) in fixed display order; the first matching tag decides the section.
SECTIONS: tuple[tuple[str, str], ...] = (
    ("backend", "Backend"),
    ("dashboard", "Dashboard"),
    ("ops", "Operations"),
    ("qa", "Quality"),
    ("decision", "Decisions"),
    ("other", "Other changes"),
)


def validate_version(version: Any) -> str:
    """Return the version unchanged or raise ValidationError."""
    if not isinstance(version, str) or not VERSION_RE.fullmatch(version):
        raise ValidationError("version must look like v1.4 or v1.4.2")
    return version


def release_tag(version: str) -> str:
    return f"release:{version}"


def section_key(note: dict[str, Any]) -> str:
    """Key of the first section (in fixed order) whose key is among the note's tags."""
    tags = set(note.get("tags") or [])
    for key, _ in SECTIONS[:-1]:
        if key in tags:
            return key
    return "other"


def group_notes(notes: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Group notes into non-empty sections in fixed order; each note appears once."""
    buckets: dict[str, list[dict[str, Any]]] = {key: [] for key, _ in SECTIONS}
    for note in notes:
        buckets[section_key(note)].append(note)
    return [{"key": key, "title": title, "notes": buckets[key]} for key, title in SECTIONS if buckets[key]]


def build_release_notes(service: NoteService, version: str) -> dict[str, Any]:
    """Build the JSON payload for a release. Raises ValidationError for a bad version."""
    validate_version(version)
    tag = release_tag(version)
    # A tag over the tag limit cannot exist on any note, so the release is empty.
    notes = service.list(tag=tag) if len(tag) <= MAX_TAG else []
    sections = group_notes(notes)
    return {
        "version": version,
        "count": sum(len(s["notes"]) for s in sections),
        "sections": sections,
    }


def _first_line(body: str) -> str:
    for line in (body or "").splitlines():
        if line.strip():
            return line.strip()
    return ""


def render_markdown(release: dict[str, Any]) -> str:
    """Render a build_release_notes payload as Markdown."""
    lines = [f"# Release {release['version']}"]
    for section in release["sections"]:
        lines += ["", f"## {section['title']}"]
        for note in section["notes"]:
            first = _first_line(note.get("body", ""))
            lines.append(f"- {note['title']}: {first}" if first else f"- {note['title']}")
    return "\n".join(lines) + "\n"

