    console.error("Could not copy", err);
    return false;
  }
}

export async function initReleaseNotes() {
  const body = document.getElementById("release-notes-body");
  const summary = document.getElementById("release-notes-summary");
  const button = document.getElementById("release-notes-copy");
  const status = document.getElementById("release-notes-status");
  if (!body || !button) return;
  const nameEl = document.getElementById("release-name");
  const version = nameEl ? nameEl.textContent.trim() : "v1.4";

  let flash;
  const say = (msg) => {
    status.textContent = msg;
    clearTimeout(flash);
    flash = setTimeout(() => { status.textContent = ""; }, 3000);
  };

  button.addEventListener("click", async () => {
    const md = await fetchReleaseMarkdown(version);
    if (md === null) return say("Could not load notes");
    say((await copyText(md)) ? "Copied!" : "Copy failed");
  });

  const data = await fetchReleaseNotes(version);
  if (!data) {
    body.innerHTML = `<p class="empty">Release notes unavailable.</p>`;
    summary.textContent = "";
    return;
  }
  summary.textContent = summaryText(data);
  body.innerHTML = renderReleaseNotesHtml(data);
}

