import test from "node:test";
import assert from "node:assert/strict";
import {
  RELEASE_VERSION_RE,
  buildMarkdown,
  escapeHtml,
  firstBodyLine,
  isValidVersion,
  releaseNotesUrl,
  renderNoteItem,
  renderReleaseNotesHtml,
  renderSection,
  summaryText,
} from "../js/release-notes.js";

const note = (over = {}) => ({
  id: 1,
  title: "Add endpoint",
  body: "first line\nsecond line",
  tags: ["backend", "release:v1.4"],
  created_at: "2026-11-01T00:00:00Z",
  updated_at: "2026-11-01T00:00:00Z",
  ...over,
});
const data = {
  version: "v1.4",
  count: 3,
  sections: [
    { key: "backend", title: "Backend", notes: [note(), note({ id: 2, title: "No body", body: "" })] },
    { key: "qa", title: "Quality", notes: [note({ id: 3, title: "Smoke", body: "\n\n  ran it  \nmore" })] },
  ],
};
const empty = { version: "v1.4", count: 0, sections: [] };

test("version regex matches the API contract", () => {
  for (const v of ["v1.4", "v10.0", "v1.4.2"]) assert.equal(isValidVersion(v), true, v);
  for (const v of ["1.4", "v1", "v1.4.", "v1.4.2.3", "V1.4", "v1.x", "v1.4-rc1", "", " v1.4", "v1.4\n"]) {
    assert.equal(isValidVersion(v), false, JSON.stringify(v));
  }
  assert.equal(isValidVersion(null), false);
  assert.equal(isValidVersion(undefined), false);
  assert.equal(RELEASE_VERSION_RE.test("v1.4"), true);
});

test("releaseNotesUrl builds the json and markdown urls", () => {
  assert.equal(releaseNotesUrl("v1.4"), "/api/releases/v1.4/notes");
  assert.equal(releaseNotesUrl("v1.4.2", "markdown"), "/api/releases/v1.4.2/notes?format=markdown");
});

test("releaseNotesUrl refuses an invalid version", () => {
  assert.throws(() => releaseNotesUrl("../x"));
  assert.throws(() => releaseNotesUrl("1.4"));
});

test("escapeHtml escapes & < > quotes and is null-safe", () => {
  assert.equal(escapeHtml(`<a href="x" onclick='y'>&</a>`), "&lt;a href=&quot;x&quot; onclick=&#39;y&#39;&gt;&amp;&lt;/a&gt;");
  assert.equal(escapeHtml(null), "");
  assert.equal(escapeHtml(undefined), "");
  assert.equal(escapeHtml(0), "0");
});

test("firstBodyLine returns the first non-empty trimmed line", () => {
  assert.equal(firstBodyLine("\n\n  ran it  \nmore"), "ran it");
  assert.equal(firstBodyLine("a\r\nb"), "a");
  assert.equal(firstBodyLine(""), "");
  assert.equal(firstBodyLine("  \n \n"), "");
  assert.equal(firstBodyLine(null), "");
});

test("renderNoteItem shows title and first body line only", () => {
  const html = renderNoteItem(note());
  assert.match(html, /Add endpoint/);
  assert.match(html, /first line/);
  assert.doesNotMatch(html, /second line/);
});

test("renderNoteItem escapes every API value", () => {
  const html = renderNoteItem(note({ title: "<img src=x onerror=1>", body: "<script>alert(1)</script>", tags: ['"><b>'] }));
  assert.doesNotMatch(html, /<img/);
  assert.doesNotMatch(html, /<script/);
  assert.doesNotMatch(html, /<b>/);
  assert.match(html, /&lt;img/);
  assert.match(html, /&lt;script&gt;/);
});

test("renderNoteItem tolerates a note with no body or tags", () => {
  const html = renderNoteItem({ title: "Bare" });
  assert.match(html, /Bare/);
  assert.doesNotMatch(html, /undefined|null/);
});

test("renderSection escapes title and key and renders each note", () => {
  const html = renderSection({ key: 'x"y', title: "<b>T</b>", notes: [note(), note({ id: 2, title: "Second" })] });
  assert.doesNotMatch(html, /<b>T/);
  assert.match(html, /&lt;b&gt;T/);
  assert.doesNotMatch(html, /x"y/);
  assert.match(html, /Add endpoint/);
  assert.match(html, /Second/);
});

test("renderReleaseNotesHtml renders every section in order", () => {
  const html = renderReleaseNotesHtml(data);
  assert.ok(html.indexOf("Backend") !== -1 && html.indexOf("Backend") < html.indexOf("Quality"));
  assert.match(html, /Smoke/);
});

test("renderReleaseNotesHtml renders no section markup when there are no sections", () => {
  const html = renderReleaseNotesHtml(empty);
  assert.equal(typeof html, "string");
  assert.doesNotMatch(html, /release-section|<h3|<li/);
});

test("summaryText pluralises and handles empty", () => {
  assert.equal(summaryText(data), "3 notes in 2 sections");
  assert.equal(summaryText({ count: 1, sections: [{ key: "ops", title: "Operations", notes: [note()] }] }), "1 note in 1 section");
  assert.match(summaryText(empty), /no notes/i);
});

test("buildMarkdown mirrors the server markdown", () => {
  assert.equal(
    buildMarkdown(data),
    "# Release v1.4\n\n## Backend\n- Add endpoint: first line\n- No body\n\n## Quality\n- Smoke: ran it\n",
  );
});

test("buildMarkdown of an empty release is only the heading", () => {
  assert.equal(buildMarkdown(empty), "# Release v1.4\n");
});

